{"file_path":"src/diff.js","content":"/**
 * Compute the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines with an "earliest matches" tie-break.
 *
 * Returns a list of changes, each `{ baseStart, baseEnd, sideStart, sideEnd }`,
 * ordered by where they start in `base`.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) dp[i][j] = dp[i + 1][j + 1] + 1
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let changeStartI = null
  let changeStartJ = null

  const flush = (endI, endJ) => {
    if (changeStartI !== null) {
      changes.push({ baseStart: changeStartI, baseEnd: endI, sideStart: changeStartJ, sideEnd: endJ })
      changeStartI = null
      changeStartJ = null
    }
  }

  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++
      j++
    } else {
      if (changeStartI === null) {
        changeStartI = i
        changeStartJ = j
      }
      if (dp[i + 1][j] >= dp[i][j + 1]) i++
      else j++
    }
  }

  if (i < n || j < m) {
    if (changeStartI === null) {
      changeStartI = i
      changeStartJ = j
    }
    i = n
    j = m
  }
  flush(i, j)

  return changes
}
"}

