/**
 * Compute the merge regions between `mine`, `base` and `theirs`.
 *
 * Returns a list of region descriptors, each one of:
 *  - { kind: 'stable', lines }
 *  - { kind: 'mine' | 'theirs' | 'both', lines }
 *  - { kind: 'conflict', mine, base, theirs }
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges]
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  let idx = 0
  while (idx < all.length) {
    const group = [all[idx]]
    let baseStart = all[idx].baseStart
    let baseEnd = all[idx].baseEnd
    idx++
    while (idx < all.length && all[idx].baseStart <= baseEnd) {
      group.push(all[idx])
      if (all[idx].baseEnd > baseEnd) baseEnd = all[idx].baseEnd
      idx++
    }
    groups.push({ baseStart, baseEnd, group })
  }

  const regions = []
  let pos = 0

  const pushStable = (start, end) => {
    if (end > start) {
      regions.push({ kind: 'stable', lines: base.slice(start, end) })
    }
  }

  for (const { baseStart, baseEnd, group } of groups) {
    pushStable(pos, baseStart)

    const mineOwn = group.filter(c => c.side === 'mine')
    const theirsOwn = group.filter(c => c.side === 'theirs')

    const baseLines = base.slice(baseStart, baseEnd)

    const sideLines = (own, doc) => {
      if (own.length === 0) return base.slice(baseStart, baseEnd)
      const first = own[0]
      const last = own[own.length - 1]
      const start = first.sideStart - (first.baseStart - baseStart)
      const end = last.sideEnd + (baseEnd - last.baseEnd)
      return doc.slice(start, end)
    }

    const mineLines = sideLines(mineOwn, mine)
    const theirsLines = sideLines(theirsOwn, theirs)

    const mineTouched = mineOwn.length > 0
    const theirsTouched = theirsOwn.length > 0

    if (!mineTouched && !theirsTouched) {
      pushStable(baseStart, baseEnd)
    } else if (mineTouched && !theirsTouched) {
      regions.push({ kind: 'mine', lines: mineLines })
    } else if (!mineTouched && theirsTouched) {
      regions.push({ kind: 'theirs', lines: theirsLines })
    } else {
      if (linesEqual(mineLines, theirsLines)) {
        regions.push({ kind: 'both', lines: mineLines })
      } else if (linesEqual(mineLines, baseLines)) {
        regions.push({ kind: 'theirs', lines: theirsLines })
      } else if (linesEqual(theirsLines, baseLines)) {
        regions.push({ kind: 'mine', lines: mineLines })
      } else {
        regions.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
      }
    }

    pos = baseEnd
  }

  pushStable(pos, base.length)

  return regions
