{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeRegions } from './merge.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const input = readStdin()
  const lines = splitLines(input)

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }

  if (parts.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }

  const [mine, base, theirs] = parts
  const regions = computeRegions(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`)
      } else {
        out.push(`${region.kind} ${region.lines.length}\n`)
      }
    }
  } else {
    const withBase = mode === 'merge'
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine\n')
        for (const l of region.mine) out.push(`${l}\n`)
        if (withBase) {
          out.push('||||||| base\n')
          for (const l of region.base) out.push(`${l}\n`)
        }
        out.push('=======\n')
        for (const l of region.theirs) out.push(`${l}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const l of region.lines) out.push(`${l}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(conflict ? 1 : 0)
}

main()
"}

